function factorial(n) {
  if (n < 0) {
    throw new Error("参数错误");
  }

  if (n <= 1) {
    return 1;
  }

  return n * factorial(n - 1);
}

function factorial(n, result = 1) {
  if (n < 0) {
    throw new Error("参数错误");
  }

  if (n <= 1) {
    return result;
  }

  return factorial(n - 1, result * n);
}
